const practiceLevels = {
  basic: {label:'Nhận biết', description:'Nhận diện khái niệm và dùng công thức trực tiếp.'},
  apply: {label:'Vận dụng', description:'Chọn cách giải và kết nối các dữ kiện trong đề.'},
  challenge: {label:'Nâng cao', description:'Thử bài cần nhiều bước hoặc phải giải thích bản chất.'}
};

const expansions = [grade10, grade11, grade12, semesterFoundations, semesterHydrocarbons, semesterAlcohol];
const detailsById = Object.assign({}, ...expansions.map(grade => grade.details));
const extraLessons = new Map(expansions.flatMap(grade => grade.extra).map(lesson => [lesson.id, lesson]));
const extraAfter = {
  mol:['limiting','concentration'], ph:['titration'], organic:['spectra','separation'],
  hydrocarbon:['hydrocarbon-methods','halogen-derivatives'], alcohol:['alcohol-properties','carbonyl'],
  amine:['protein'], cell:['electrolysis-practice']
};
const lessons = coreLessons.flatMap(lesson => [
  lesson, ...(extraAfter[lesson.id] || []).map(id => extraLessons.get(id))
]).map(lesson => {
  const {sections, examples, practice} = detailsById[lesson.id];
  const practiceByLevel = {basic:[...lesson.questions], apply:[], challenge:[]};
  for (const [level, ...question] of practice) practiceByLevel[level].push(question);
  return {
    ...lesson,
    sections,
    examples:[[lesson.example,lesson.solution], ...examples],
    practiceByLevel,
    practiceCount:lesson.questions.length + practice.length,
    written:writtenPractice[lesson.id] || []
  };
});
